"use strict";(globalThis.webpackChunkmy_website||=[]).push([[37681],{67616(e){e.exports=JSON.parse('{"slug":"info-action","title":"Info Action","short":"A CIP-1694 governance action type that records a community vote on a piece of information without enforcing any on-chain change.","category":"governance","aliases":[],"mentalModel":null,"related":["governance-action","drep","cip-1694","conway-era","chang"],"sources":[],"link":"/governance","level":"intermediate","body":"An information-only governance action defined by CIP-1694. Info actions let DReps, the Constitutional Committee, and stake pool operators vote on any topic of community interest without that vote making any direct change to the ledger or treasury.\\n\\nInfo actions were the only action type DReps could vote on during the bootstrap phase between the Chang and Plomin hard forks, which made them an important on-ramp for governance participation before the full action set was unlocked."}')}}]);